import math


def hard_upsample(phonemes, durations):
    if len(phonemes) != len(durations):
        raise ValueError("one duration per phoneme is required")
    rows = []
    for encoding, duration in zip(phonemes, durations):
        count = int(round(duration))
        if count < 1:
            raise ValueError("every phoneme needs at least one frame")
        rows.extend([list(encoding) for _ in range(count)])
    return rows


def soft_alignment(durations, sigma=0.7):
    if len(durations) == 0:
        raise ValueError("no durations to align")
    if any(duration <= 0 for duration in durations):
        raise ValueError("durations must be positive")
    total = int(round(sum(durations)))
    centres = []
    running = 0.0
    for duration in durations:
        running += duration
        centres.append(running - duration / 2.0)
    matrix = []
    for frame in range(total):
        position = frame + 0.5
        row = [math.exp(-0.5 * ((position - centre) / sigma) ** 2)
               for centre in centres]
        weight = sum(row)
        matrix.append([value / weight for value in row])
    return matrix


def soft_upsample(phonemes, durations, sigma=0.7):
    if len(phonemes) != len(durations):
        raise ValueError("one duration per phoneme is required")
    matrix = soft_alignment(durations, sigma)
    width = len(phonemes[0])
    out = []
    for row in matrix:
        frame = [0.0] * width
        for weight, encoding in zip(row, phonemes):
            for index in range(width):
                frame[index] += weight * encoding[index]
        out.append(frame)
    return out


def blend_style(sampled, reference, alpha):
    if not 0.0 <= alpha <= 1.0:
        raise ValueError("alpha must be between 0 and 1")
    if len(sampled) != len(reference):
        raise ValueError("style vectors must have the same dimension")
    return [alpha * s + (1 - alpha) * r for s, r in zip(sampled, reference)]


def difference(a, b):
    return sum(abs(x - y) for row_a, row_b in zip(a, b)
               for x, y in zip(row_a, row_b))
